local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path;local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local path=b.lib('path');local time=b.lib('time');local host=b.lib('host');local root=path.absolute(a.required(o,'evidence-dir'));local markers={path.join(root,'team-1-renderer-screenshot.tick'),path.join(root,'team-2-renderer-screenshot.tick')};assert(time.poll(30000,100,function()return path.is_file(markers[1])and path.is_file(markers[2])end),'renderer screenshot tick timeout');local tick1=tonumber(path.read(markers[1]));local tick2=tonumber(path.read(markers[2]));assert(tick1 and tick1==tick2,'renderers did not freeze at the same replica tick');time.sleep_ms(500);for team=1,2 do local pid=a.integer(a.required(o,'team'..team..'-renderer-pid'),'renderer PID',1);host.call('screenshot',{pid=pid,output=path.join(root,'team-'..team..'-screenshot.png')})end
